# -*- coding: utf-8 -*-
"""ledger_r110.py -- write reviews/NUMBERS_R110.md from the Phase 1 result files (CC_PASS_v18, program R110). NO MODEL CALL.
Regenerated whole from reviews/v18/results/a{1,2,3,4}_*.json; every number the v18 manuscript prints from Phase 1 enters
through a key in this file and no other way. Re-runnable.
"""
from __future__ import annotations

import io
import json
import pathlib

ROOT = pathlib.Path(__file__).resolve().parents[3]
RES = ROOT / "reviews" / "v18" / "results"
OUT = ROOT / "reviews" / "NUMBERS_R110.md"


def J(name):
    return json.load(io.open(RES / name, encoding="utf-8"))


def ci(d, signed=True):
    f = "{:+.4f}" if signed else "{:.4f}"
    return "[" + f.format(d["ci_lo"]) + ", " + f.format(d["ci_hi"]) + "]"


def pr(p):
    return f"{p['delta']:+.4f}; item {ci(p['item_ci'])}, persona {ci(p['persona_ci'])}" + ("*" if p["both_exclude_zero"] else "")


def main():
    a1, a2, a3, a4 = J("a1_count_readers.json"), J("a2_tag_baselines.json"), J("a3_single_draw.json"), J("a4_pad_extend.json")
    L = []
    w = L.append
    w("# NUMBERS_R110.md: the Phase 1 analyses of CC_PASS_v18 (program R110; no model call; $0)")
    w("")
    w("Generated by `reviews/v18/tools/ledger_r110.py` from `reviews/v18/results/a1_count_readers.json`, `a2_tag_baselines.json`, `a3_single_draw.json` and `a4_pad_extend.json` (2026-09-14). Every input is a recorded row; frozen lane code is imported, never edited. Estimators: `common_e1r` (Mann-Whitney AUROC, ties at 0.5; item-level and persona-clustered bootstraps, 1,000 draws, seed 42, single-class draws discarded); paired differences by `cf2_score.paired` (both intervals; an asterisk marks both excluding zero; the weaker governs). No registration: these are descriptive analyses on recorded rows, ordered by the author on 2026-09-14 in answer to review ten (W1, W2, W5, W7, Q1, Q2, Q4). Every number the v18 manuscript prints from them enters through a key here and no other way.")
    w("")
    w("Reproduction gates, all passed at four decimals before any new number printed: " + "; ".join(f"{k} {v}" for k, v in a1["gates"].items()) + f"; A2 {json.dumps(a2['gates'])}; A3 {json.dumps(a3['gates'])}; A4 {json.dumps(a4['gates'])}.")
    w("")
    # ---------------------------------------------------------------- A1
    w("## 1. AUX-R110-A1: count readers on the counterfactual set (444; primary) and the 661 (secondary)")
    w("")
    c = a1["cf444"]
    w("Readers: CR-oracle-a = RETRACT + EXPIRED at the question's manifest category (the reviewer's reader; `cf_pairs_cf2.json` `category`); CR-oracle-b adds SUPRSD; CR-oracle-share = (SUPRSD+RETRACT+EXPIRED)/ENTRIES at that category; CR-oracle-state = the state's own cell at that category (knows the state as well as the category; the upper bound of a tally reader); CR-totals-a = the two LIFECYCLE TOTALS lines (retracted + expired), the fields v2r permutes; CR-totals-b adds the superseded total; CR-nb1 = NB-1 unchanged (`index_features.assign_category`, then the lifecycle share). Per state on the 444: within the state's own items (the CF-2 convention). Category row present for every item; NB-1 assigned a category on " + str(c["summaries"]["v2"]["nb1_assigned_a_category"]) + " of 444.")
    w("")
    w("### AUX-R110-A1-V2R: what the count-randomized summary randomized, and the readers under it")
    w("")
    k = c["v2r_check"]
    w(f"v2r permutes the two LIFECYCLE TOTALS lines and leaves the PER-CATEGORY BREAKDOWN's RETRACT and EXPIRED columns untouched ({k['v2r_permutes_only_the_totals_lines']}). CR-oracle's scores are identical under v2 and v2r: **{k['CR-oracle_scores_identical_v2_v2r']}**. CR-totals-a under v2 reads whole {k['CR-totals-a']['whole']['v2']:.4f}, retraction {k['CR-totals-a']['RETRACTION']['v2']:.4f}, expiry {k['CR-totals-a']['EXPIRY']['v2']:.4f}; under the recorded v2r (seed 42) whole {k['CR-totals-a']['whole']['v2r']:.4f}, retraction **{k['CR-totals-a']['RETRACTION']['v2r']:.4f}**, expiry **{k['CR-totals-a']['EXPIRY']['v2r']:.4f}**. Over 200 derangement seeds CR-totals-a averages retraction {k['CR-totals-a_expectation_over_seeds']['derangement_200_seeds']['RETRACTION']['mean']:.4f} [{k['CR-totals-a_expectation_over_seeds']['derangement_200_seeds']['RETRACTION']['p2.5']:.4f}, {k['CR-totals-a_expectation_over_seeds']['derangement_200_seeds']['RETRACTION']['p97.5']:.4f}] and expiry {k['CR-totals-a_expectation_over_seeds']['derangement_200_seeds']['EXPIRY']['mean']:.4f} [{k['CR-totals-a_expectation_over_seeds']['derangement_200_seeds']['EXPIRY']['p2.5']:.4f}, {k['CR-totals-a_expectation_over_seeds']['derangement_200_seeds']['EXPIRY']['p97.5']:.4f}]; 200 uniform permutations {k['CR-totals-a_expectation_over_seeds']['uniform_permutation_200_seeds']['RETRACTION']['mean']:.4f} and {k['CR-totals-a_expectation_over_seeds']['uniform_permutation_200_seeds']['EXPIRY']['mean']:.4f}. Verdict: {k['verdict']}.")
    w("")
    w(f"Base-count census (the ABSENT version's category cell under v2): retraction pairs with a base count of 0: **{c['base_count_census']['RETRACTION']['base_zero']} of 30**; expiry **{c['base_count_census']['EXPIRY']['base_zero']} of 30**. Within its triple the PN version reads its increment against that base.")
    w("")
    w("### AUX-R110-A1-CR: the readers under each summary (AUROC whole; supersession / retraction / expiry; item and persona intervals on the whole set)")
    w("")
    w("| summary | reader | whole | SUP | RET | EXP | item 95% | persona 95% |")
    w("|---|---|---:|---:|---:|---:|---|---|")
    for tag in ("v2", "v3", "v2r"):
        for r, row in c["summaries"][tag]["readers"].items():
            ps = row["per_state"]; wh = row["whole"]
            w(f"| {tag} | {r} | {wh['auroc']:.4f} | {ps['SUPERSESSION']['auroc']:.4f} | {ps['RETRACTION']['auroc']:.4f} | {ps['EXPIRY']['auroc']:.4f} | {ci(wh['item_ci'], False)} | {ci(wh['persona_ci'], False)} |")
    w("")
    w("Per-state intervals for CR-oracle-a and CR-oracle-state under v2 (retraction; expiry): " + "; ".join(
        f"{r} retraction {c['summaries']['v2']['readers'][r]['per_state']['RETRACTION']['auroc']:.4f} item {ci(c['summaries']['v2']['readers'][r]['per_state']['RETRACTION']['item_ci'], False)} persona {ci(c['summaries']['v2']['readers'][r]['per_state']['RETRACTION']['persona_ci'], False)}, expiry {c['summaries']['v2']['readers'][r]['per_state']['EXPIRY']['auroc']:.4f} item {ci(c['summaries']['v2']['readers'][r]['per_state']['EXPIRY']['item_ci'], False)} persona {ci(c['summaries']['v2']['readers'][r]['per_state']['EXPIRY']['persona_ci'], False)}"
        for r in ("CR-oracle-a", "CR-oracle-state")) + ".")
    w("")
    w("### AUX-R110-A1-MODELS: model minus reader under the same summary (delta; item; persona) and the per-state levels")
    w("")
    w("| summary | reader | model | model whole | reader whole | whole delta | RET model / reader / delta | EXP model / reader / delta |")
    w("|---|---|---|---:|---:|---|---|---|")
    for tag in ("v2", "v3", "v2r"):
        for r in ("CR-oracle-a", "CR-oracle-state", "CR-totals-a", "CR-nb1"):
            row = c["summaries"][tag]["readers"][r]
            for model, vm in row["vs_models"].items():
                R, E = vm["per_state"]["RETRACTION"], vm["per_state"]["EXPIRY"]
                w(f"| {tag} | {r} | {model} | {vm['model_auroc']:.4f} | {row['whole']['auroc']:.4f} | {pr(vm['whole'])} | {R['model']:.4f} / {R['reader']:.4f} / {R['delta']:+.4f} | {E['model']:.4f} / {E['reader']:.4f} / {E['delta']:+.4f} |")
    w("")
    b = c["branch"]
    w(f"### AUX-R110-A1-BRANCH: **{b['fires']}**. The wording (the author's note of 2026-09-14: 'read weakly' withdrawn; the numbers are stated): {b['wording']}. CR-oracle-a under v2 reads retraction {b['retraction']:.4f} and expiry {b['expiry']:.4f}; the state-aware reader ({b['state_aware_upper_bound']['retraction']:.4f} / {b['state_aware_upper_bound']['expiry']:.4f}) is an upper bound and stays in Appendix C.2 with its definition. The reader claim: the tally carried the label and no model read it.")
    w("")
    o = a1["obl661"]
    w("### AUX-R110-A1-661: the secondary population (positives of one state against all negatives; no category source mixed across labels)")
    w("")
    w(f"Category source: PRESENT-NEGATIVE from `pn_members`, PRESENT and ABSENT from the gold entries, never from NB-1. Items with a gold category / dropped: " + ", ".join(f"{lab} {v['with_category']} / {v['dropped']}" for lab, v in o["with_category_vs_dropped_by_label"].items()) + f"; items with more than one target category {o['items_with_more_than_one_target_category']} (the reader takes the maximum over them).")
    w("")
    w("| reader | population | n / pos | whole | SUP | RET | EXP | item 95% | persona 95% |")
    w("|---|---|---|---:|---:|---:|---:|---|---|")
    for r, row in o["readers"].items():
        ps = row["per_state"]; wh = row["whole"]
        w(f"| {r} | {row['population']} | {row['n']} / {row['pos']} | {wh['auroc']:.4f} | {ps['SUPERSESSION']['auroc']:.4f} | {ps['RETRACTION']['auroc']:.4f} | {ps['EXPIRY']['auroc']:.4f} | {ci(wh['item_ci'], False)} | {ci(wh['persona_ci'], False)} |")
    w("")
    w("| reader | model | n | model | reader | model minus reader |")
    w("|---|---|---:|---:|---:|---|")
    for r, row in o["readers"].items():
        for model, vm in row["vs_models"].items():
            w(f"| {r} | {model} | {vm['n']} | {vm['model_auroc']:.4f} | {vm['reader_auroc']:.4f} | {pr(vm)} |")
    w("")
    # ---------------------------------------------------------------- A2
    w("## 2. AUX-R110-A2: mechanical baselines on the tagged retrieved view (the 661), both tag sources")
    w("")
    t = a2["tag_census"]
    w(f"The view is the recorded five-line block each monitor saw (`resp_review/l2/retrieval.json`, the join's tags; `retrieval_believed.json`, the store's own marks); tags and scrubbed names parsed from the block. Tag census: join {t['join']['non_active_lines']} non-active lines of {t['join']['lines']} ({t['join']['items_with_no_tagged_line']} items with no tagged line); own marks {t['own']['non_active_lines']} of {t['own']['lines']} ({t['own']['items_with_no_tagged_line']} items with none); {a2['gates']['tag_census']['lines_changed']} lines change tag between the sources (the recorded lock). Per state: positives of one state against all negatives. TD = fraction of the five lines tagged non-active; TL = max cosine (all-MiniLM-L6-v2) between the question and the scrubbed names of the tagged lines (0 when none); TL-all = over all five lines; HL = max(superseded-names lookup, TL); FR = the indicator that the item's forbidding record is in view and tagged non-active under the source (1 for an obligation item when one of its pn_members is among the five lines and that line's tag is non-active; 0 for every other item; the author's follow-up of 2026-09-14). Paired against the monitor that saw the same input (monitor minus baseline). No hybrid monitor under own marks was run; HL under own marks is paired against RETRIEVED-BELIEVED and HYBRID with that stated.")
    w("")
    w("| tag source | baseline | whole | SUP | RET | EXP | item 95% | persona 95% | distinct values |")
    w("|---|---|---:|---:|---:|---:|---|---|---:|")
    for src in ("join", "own", "lookup"):
        for name, row in a2["baselines"][src].items():
            ps = row["per_state"]; wh = row["whole"]
            w(f"| {src} | {name} | {wh['auroc']:.4f} | {ps['SUPERSESSION']['auroc']:.4f} | {ps['RETRACTION']['auroc']:.4f} | {ps['EXPIRY']['auroc']:.4f} | {ci(wh['item_ci'], False)} | {ci(wh['persona_ci'], False)} | {row['distinct_values']} |")
    w("")
    w("Monitors (whole; SUP / RET / EXP): " + "; ".join(f"{n} {m['whole']:.4f} ({m['per_state']['SUPERSESSION']:.4f} / {m['per_state']['RETRACTION']:.4f} / {m['per_state']['EXPIRY']:.4f})" for n, m in a2["monitors"].items()) + ".")
    w("")
    w("| tag source | baseline | monitor | monitor | baseline | monitor minus baseline |")
    w("|---|---|---|---:|---:|---|")
    for src in ("join", "own", "lookup"):
        for name, row in a2["baselines"][src].items():
            for mname, vm in row["vs_monitor"].items():
                w(f"| {src} | {name} | {mname} | {vm['monitor']:.4f} | {vm['baseline']:.4f} | {pr(vm['whole'])} |")
    w("")
    w("### AUX-R110-A2-OWNVSJOIN: the same reader under the store's own marks minus under the join's tags (paired), and the forbidding-record census")
    w("")
    w("| reader | join | own | own minus join |")
    w("|---|---:|---:|---|")
    for name, d in a2["own_minus_join"].items():
        w(f"| {name} | {d['join']:.4f} | {d['own']:.4f} | {pr(d)} |")
    fi, fg = a2["fr_items"], a2["gates"]["forbidding_records_in_view"]
    w("")
    w(f"Obligation items {fi['obligation_items']}; with a forbidding record among the five lines {fi['with_a_forbidding_record_in_view']}; in view and tagged non-active under the join {fi['in_view_and_tagged_join']}, under the store's own marks {fi['in_view_and_tagged_own']}. At the record level (the recorded lock, `lock_amend1.json` forbidding_records_in_view, reproduced): {fg['in_view']} forbidding records in view, {fg['tagged_own']} tagged non-active under the marks against {fg['tagged_join']} under the join.")
    w("")
    br = a2["branches"]
    rb = br["reach_explains_the_rise"]
    w(f"### AUX-R110-A2-REACH: TL and FR both higher under the marks: **{rb['fires']}** (TL {rb['TL_join']:.4f} to {rb['TL_own']:.4f}; FR {rb['FR_join']:.4f} to {rb['FR_own']:.4f}). {rb['wording']}")
    w("")
    w(f"### AUX-R110-A2-BRANCH: B1 (density explains own marks) fires **{br['B1_density_explains_own_marks']['fires']}** (TD under own marks {br['B1_density_explains_own_marks']['TD_own']:.4f} against the threshold {br['B1_density_explains_own_marks']['threshold']:.4f}); B2 (a lookup within 0.05 of its monitor on the tag route) fires **{br['B2_lookup_reads_tag_route']['fires']}**" + (" (" + "; ".join(br["B2_lookup_reads_tag_route"]["hits"]) + ")" if br["B2_lookup_reads_tag_route"]["hits"] else "") + f"; B3 (the monitor reads more than density or name match) fires **{br['B3_monitor_reads_more']['fires']}**.")
    w("")
    # ---------------------------------------------------------------- A3
    w("## 3. AUX-R110-A3: single-draw scores for the five-call models, and the resolution confound")
    w("")
    w("Per model and set: the AUROC of each draw, the five-draw mean (the recorded X4 collapse), distinct score values, and the paired difference against the superseded-names lookup (model minus lookup; 444: the lookup on v2, 0.7663; 661: the lookup on the TRUE section, 0.7484).")
    w("")
    w("| set | model | per-draw AUROC (distinct values) | spread | mean AUROC (distinct) | mean minus lookup | draw 1 AUROC (distinct) | draw 1 minus lookup |")
    w("|---|---|---|---:|---|---|---|---|")
    for setname, label in (("cf444", "444"), ("obl661", "661")):
        for model, r in a3[setname].items():
            pd = r["per_draw"]; ks = r["draws_present"]
            per = ", ".join(f"d{d} {pd[str(d)]['auroc']:.4f} ({pd[str(d)]['distinct_values']})" for d in ks)
            spread = f"{r['range_across_draws']['spread']:.4f}" if r["range_across_draws"] else "0"
            d1 = r.get("draw1")
            w(f"| {label} | {model} | {per} | {spread} | {r['mean']['auroc']:.4f} ({r['mean']['distinct_values']}) | {pr(r['mean']['vs_lookup'])} | " + (f"{d1['auroc']:.4f} ({d1['distinct_values']})" if d1 and len(ks) > 1 else "k = 1") + " | " + (pr(d1["vs_lookup"]) if d1 and len(ks) > 1 else "") + " |")
    w("")
    mr = a3["mini_redraw"]
    w(f"GPT-4.1 mini's redraw stability (recorded): the 50-question blind redraw at k = 3 returned identical scores on {mr['k3_blind_50']['identical_across_3']} of {mr['k3_blind_50']['n_questions']} questions (mean spread {mr['k3_blind_50']['mean_spread']}, max {mr['k3_blind_50']['max_spread']}; `e1_metamemory/results/scores_e1.json` k3_noise); the 102-prompt TRUE redraw moved the whole-population score by {mr['true_redraw_102']['D']:+.4f} (item [{mr['true_redraw_102']['item']['ci_lo']:+.4f}, {mr['true_redraw_102']['item']['ci_hi']:+.4f}]; AUX-RESP-L1-REDRAW). Extra mini calls at temperature 0 would not add resolution.")
    w("")
    b3 = a3["branch"]
    w(f"### AUX-R110-A3-BRANCH: **{b3['fires']}**. Opus 5 draw 1 minus the lookup on the 444: {b3['opus_draw1_minus_lookup_444']:+.4f}, item [{b3['item_ci'][0]:+.4f}, {b3['item_ci'][1]:+.4f}], persona [{b3['persona_ci'][0]:+.4f}, {b3['persona_ci'][1]:+.4f}]. {b3['wording']}")
    w("")
