        for Lreq, r in a4["readings"][reading].items():
            e, l = r["lookups"]["emb"], r["lookups"]["lex"]; n = r["names_per_item"]
            w(f"| {lab} | {Lreq} | {n['mean']:.1f}; {n['min']}; {n['max']}; {n['at_L']} of {n['n_rows']} | {r['keys_spilling_into_pool_b']} ({r['names_from_pool_b_total']}) | {e['auroc']:.4f} | {ci(e['item_ci'], False)} | {ci(e['persona_ci'], False)} | {e['per_state']['superseded']['auroc']:.4f} / {e['per_state']['retracted']['auroc']:.4f} / {e['per_state']['expired']['auroc']:.4f} | {pr(r['paired_vs_base']['emb'])} | {l['auroc']:.4f} | {ci(l['item_ci'], False)} |")
