        ("53, 17, 12", f"{a3['cf444']['claude-opus-5']['draw1']['distinct_values']}, {a3['cf444']['claude-haiku-4-5-20251001']['draw1']['distinct_values']}, {a3['cf444']['gpt-4.1-mini']['mean']['distinct_values']}", "distinct score values in one draw on the 444: Opus 5, Haiku 4.5, GPT-4.1 mini (AUX-R110-A3)"),
